import React, { useState, useEffect, useMemo, useCallback } from 'react';

// --- Types & Interfaces ---

export interface JwtHeader {
  alg?: string;
  typ?: string;
  kid?: string;
  x5t?: string;
  [key: string]: unknown;
}

export interface ChaseJwtClaims {
  iss?: string;
  sub?: string;
  aud?: string | string[];
  exp?: number;
  nbf?: number;
  iat?: number;
  jti?: string;
  client_id?: string;
  scope?: string;
  channel_type?: string;
  partner_id?: string;
  account_ref_uuid?: string;
  ext_acct_id?: string;
  token_type?: string;
  roles?: string[];
  [key: string]: unknown;
}

export interface JwksKey {
  kty: string;
  kid: string;
  use?: string;
  alg?: string;
  n?: string;
  e?: string;
}

export interface ValidationCheck {
  id: string;
  title: string;
  status: 'passed' | 'failed' | 'warning' | 'info';
  details: string;
}

export interface DecodedToken {
  header: JwtHeader;
  payload: ChaseJwtClaims;
  signature: string;
  rawHeader: string;
  rawPayload: string;
}

